/**
 * The audit leaf — what actually gets committed to Bitcoin.
 *
 * ## The question this module answers
 *
 * Replacing a correspondent-banking leg with a stablecoin rail means a regulator
 * must be able to audit the payment as thoroughly as they could audit an MT103.
 * That splits into two decisions, and conflating them is the usual mistake:
 *
 *   1. **What is kept as evidence** — contracts, KYB logs, the IVMS 101 message,
 *      fiat vouchers. These stay off-chain with the party that holds the legal
 *      duty for them, because they contain the actual data.
 *   2. **What is committed on-chain** — exactly one 32-byte value per payment,
 *      and nothing else.
 *
 * ## Why the committed value is salted
 *
 * A bare `SHA-256` of the audit fields would be a re-identification channel into
 * a public, permanent ledger. The fields include a settlement id shaped like
 * `VN-SG-20261104-0007`, a bank approval reference that is often sequential, and
 * — worst — a digest of an IVMS 101 message carrying the originator's name and
 * tax identifier. Anyone holding a candidate identity could enumerate the small
 * space of plausible values and **confirm** that a named company made a
 * particular payment on a particular corridor on a particular day. The data
 * would not be published, yet the fact would be.
 *
 * So the commitment is:
 *
 * ```text
 * leaf = SHA-256( "attest:settlement:v1\n" || salt(32B) || JCS(audit fields) )
 * ```
 *
 * The salt is per settlement, generated by the submitting party, and held with
 * the Layer 2 evidence. It never goes on-chain and we never need it again.
 *
 * What each party can then do:
 *
 * | Holds | Can verify the payment | Can learn anything from the chain |
 * |---|---|---|
 * | Bundle + salt (regulator, bank) | yes, completely | — |
 * | Chain only (anyone) | no | **nothing** |
 * | StoneHash, after the fact | cannot alter it | — |
 *
 * That last row is the point of anchoring at all: Layer 1 is held by the bank
 * and the bank could rewrite it; Layer 2 is held by the two VASPs and either
 * could rewrite its copy; Layer 3 cannot be rewritten by anybody, including us.
 *
 * ## Determinism
 *
 * Field selection is fixed and the serialisation is canonical, so the same
 * settlement and salt always produce the same leaf — which is what lets an
 * auditor recompute it years later from the bundle alone.
 */
import { sha256, bytesToHex, hexToBytes, concat, utf8, jcs } from '@stonehash/attest-verify';
import type { JcsValue } from '@stonehash/attest-verify';
import type { SettlementEvidence } from './types.ts';

/** Domain tag. Keeps this preimage space disjoint from every other digest. */
export const SETTLEMENT_LEAF_DOMAIN = 'attest:settlement:v1\n';

/** Minimum salt length. 32 bytes puts brute force out of reach permanently. */
export const MIN_SALT_BYTES = 32;

/**
 * The fields committed on-chain, by name.
 *
 * Fixed and ordered, because an auditor recomputing the leaf must select exactly
 * the same fields. Adding one is a new leaf version, not an edit.
 *
 * Each is a *reference or digest*, never content: the invoice digest rather than
 * the invoice, the IVMS 101 digest rather than the names. The committed value
 * says "these documents existed in this state at this time", which is what a
 * regulator needs to detect later alteration — and nothing more.
 */
export const COMMITTED_FIELDS = [
  /** Replaces the SWIFT UETR: one id tying voucher, Travel Rule message and chain tx together. */
  'settlementId',
  /** Authorised instruction reference, plus the regulator report id where one exists. */
  'bankApprovalRef',
  'regulatorReportRef',
  /** Digest of the commercial documents (contract, invoice, customs). */
  'documentDigest',
  /** Digest of the IVMS 101 message exchanged between the two VASPs. */
  'travelRuleDigest',
  /** The receiving VASP's signed approval — proof the pre-flight gate was honoured. */
  'travelRuleApprovalDigest',
  /** Settlement-chain transaction reference. */
  'chainTxRef',
  /** Fiat leg: the deposit reference the beneficiary reconciles against. */
  'fiatDeliveryRef',
  /** Present only on a refund, pointing back at the original. */
  'relatedSettlementId',
  'refundReasonCode',
] as const;

export type CommittedField = (typeof COMMITTED_FIELDS)[number];

/** The selected fields, as they are serialised. Absent fields are omitted. */
export type AuditFields = Partial<Record<CommittedField, string>>;

/**
 * Select the committed fields from settlement evidence.
 *
 * Exported so an auditor can see precisely what was selected rather than
 * inferring it, and so the Playground can show it beside the leaf.
 */
export function selectAuditFields(ev: SettlementEvidence): AuditFields {
  const el = ev.elements ?? {};
  const out: AuditFields = {};
  const put = (k: CommittedField, v: string | undefined | null): void => {
    if (typeof v === 'string' && v !== '') out[k] = v;
  };
  put('settlementId', ev.settlementId);
  put('bankApprovalRef', el.bankApproval?.approvalRef ?? el.bankInstruction?.ref);
  put('regulatorReportRef', el.bankApproval?.regulatorReportRef);
  put('documentDigest', el.commercialDocs?.digest);
  put('travelRuleDigest', el.travelRule?.ivms101Digest);
  put('travelRuleApprovalDigest', el.travelRule?.approvalDigest);
  put('chainTxRef', el.chainTransfer?.txRef);
  put('fiatDeliveryRef', el.payoutReceipts?.[0]?.ref);
  put('relatedSettlementId', ev.relatedSettlementId);
  put('refundReasonCode', ev.refundReasonCode);
  return out;
}

export interface AuditLeaf {
  /** 64 lowercase hex. This is what goes into the Merkle tree. */
  leafBytes: string;
  /** The fields that were committed, for display and for recomputation. */
  fields: AuditFields;
  /** Salt length actually used, so a reviewer can see it met the floor. */
  saltBytes: number;
}

/**
 * Compute the audit leaf.
 *
 * `saltHex` is held by the submitting party with its Layer 2 evidence. It is
 * required rather than defaulted: a convenience default would eventually be
 * reused, and a reused salt reopens the enumeration it exists to close.
 */
export function auditLeaf(ev: SettlementEvidence, saltHex: string): AuditLeaf {
  const salt = hexToBytes(saltHex);
  if (salt.length < MIN_SALT_BYTES) {
    throw new Error(
      `settlement salt must be at least ${MIN_SALT_BYTES} bytes, got ${salt.length}. `
      + 'A short salt leaves the committed fields open to enumeration, which is the '
      + 'single thing this construction exists to prevent.');
  }
  const fields = selectAuditFields(ev);
  if (!fields.settlementId) {
    throw new Error('settlementId is required: it is what ties the voucher, the Travel Rule '
      + 'message and the chain transaction to one payment, as a UETR does on SWIFT');
  }
  const leaf = sha256(concat(utf8(SETTLEMENT_LEAF_DOMAIN), salt, jcs(fields as JcsValue)));
  return { leafBytes: bytesToHex(leaf), fields, saltBytes: salt.length };
}

/**
 * Recompute and compare — the check an auditor performs.
 *
 * Returns the recomputed leaf alongside the verdict so a mismatch can be shown
 * rather than merely reported.
 */
export function verifyAuditLeaf(
  ev: SettlementEvidence, saltHex: string, expectedLeafHex: string,
): { ok: boolean; computed: string; fields: AuditFields } {
  const { leafBytes, fields } = auditLeaf(ev, saltHex);
  return {
    ok: leafBytes === expectedLeafHex.toLowerCase(),
    computed: leafBytes,
    fields,
  };
}

/**
 * Fields that must never appear in the committed set as plain content.
 *
 * A guardrail, not a classifier. Someone extending `COMMITTED_FIELDS` with
 * `originatorName` would produce a perfectly working leaf that quietly published
 * a salted-but-still-targetable personal identifier, and nothing else in the
 * pipeline would object. This makes that a loud failure instead.
 */
const FORBIDDEN_IN_LEAF = [
  'name', 'address', 'passport', 'taxid', 'tax_id', 'nationalid', 'national_id',
  'accountnumber', 'account_number', 'iban', 'dob', 'dateofbirth', 'phone', 'email',
];

/**
 * Assert the committed field set carries no personal data.
 *
 * Travel Rule content is exactly what FATF R.16 requires the two VASPs to
 * exchange *privately*; committing it to a public ledger — even hashed — would
 * trade a transmission obligation for a permanent disclosure. Only its digest
 * belongs in the leaf.
 */
export function assertNoPiiInLeaf(fields: AuditFields): void {
  for (const key of Object.keys(fields)) {
    const flat = key.toLowerCase().replace(/[^a-z]/g, '');
    for (const bad of FORBIDDEN_IN_LEAF) {
      if (flat.includes(bad)) {
        throw new Error(
          `refusing to commit field "${key}": it names personal data. Travel Rule content is `
          + 'exchanged privately between VASPs under FATF R.16 — only its digest may be '
          + 'anchored, never the data or a field derived from it.');
      }
    }
  }
}
